// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {

	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)

	// (POST /auth/register)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)
	// Get all customers
	// (GET /customers)
	ListCustomers(ctx context.Context, request ListCustomersRequestObject) (ListCustomersResponseObject, error)

	// (POST /customers)
	CreateCustomer(ctx context.Context, request CreateCustomerRequestObject) (CreateCustomerResponseObject, error)

	// (DELETE /customers/{id})
	SoftDeleteCustomer(ctx context.Context, request SoftDeleteCustomerRequestObject) (SoftDeleteCustomerResponseObject, error)
	// Get customer by ID
	// (GET /customers/{id})
	GetCustomerById(ctx context.Context, request GetCustomerByIdRequestObject) (GetCustomerByIdResponseObject, error)

	// (PUT /customers/{id})
	UpdateCustomer(ctx context.Context, request UpdateCustomerRequestObject) (UpdateCustomerResponseObject, error)

	// (GET /dashboard)
	GetDashboard(ctx context.Context, request GetDashboardRequestObject) (GetDashboardResponseObject, error)
	// List all expenses
	// (GET /expenses)
	ListExpenses(ctx context.Context, request ListExpensesRequestObject) (ListExpensesResponseObject, error)
	// Create new expense (pengeluaran)
	// (POST /expenses)
	CreateExpense(ctx context.Context, request CreateExpenseRequestObject) (CreateExpenseResponseObject, error)
	// Soft delete expense
	// (DELETE /expenses/{id})
	SoftDeleteExpense(ctx context.Context, request SoftDeleteExpenseRequestObject) (SoftDeleteExpenseResponseObject, error)
	// Get expense by ID
	// (GET /expenses/{id})
	GetExpense(ctx context.Context, request GetExpenseRequestObject) (GetExpenseResponseObject, error)
	// Update expense
	// (PUT /expenses/{id})
	UpdateExpense(ctx context.Context, request UpdateExpenseRequestObject) (UpdateExpenseResponseObject, error)

	// (GET /health)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)

	// (GET /payment-methods)
	ListPaymentMethods(ctx context.Context, request ListPaymentMethodsRequestObject) (ListPaymentMethodsResponseObject, error)

	// (GET /reports/profit-loss)
	ProfitLossReport(ctx context.Context, request ProfitLossReportRequestObject) (ProfitLossReportResponseObject, error)
	// Get all service categories
	// (GET /service-categories)
	ListServiceCategories(ctx context.Context, request ListServiceCategoriesRequestObject) (ListServiceCategoriesResponseObject, error)

	// (POST /service-categories)
	CreateServiceCategory(ctx context.Context, request CreateServiceCategoryRequestObject) (CreateServiceCategoryResponseObject, error)

	// (DELETE /service-categories/{id})
	SoftDeleteServiceCategory(ctx context.Context, request SoftDeleteServiceCategoryRequestObject) (SoftDeleteServiceCategoryResponseObject, error)

	// (GET /service-categories/{id})
	GetServiceCategoryById(ctx context.Context, request GetServiceCategoryByIdRequestObject) (GetServiceCategoryByIdResponseObject, error)

	// (PUT /service-categories/{id})
	UpdateServiceCategory(ctx context.Context, request UpdateServiceCategoryRequestObject) (UpdateServiceCategoryResponseObject, error)
	// Get all services with category name
	// (GET /services)
	ListServices(ctx context.Context, request ListServicesRequestObject) (ListServicesResponseObject, error)
	// Create new service
	// (POST /services)
	CreateService(ctx context.Context, request CreateServiceRequestObject) (CreateServiceResponseObject, error)

	// (DELETE /services/{id})
	SoftDeleteService(ctx context.Context, request SoftDeleteServiceRequestObject) (SoftDeleteServiceResponseObject, error)

	// (GET /services/{id})
	GetServiceById(ctx context.Context, request GetServiceByIdRequestObject) (GetServiceByIdResponseObject, error)

	// (PUT /services/{id})
	UpdateService(ctx context.Context, request UpdateServiceRequestObject) (UpdateServiceResponseObject, error)

	// (GET /services/{id}/detail)
	GetServiceDetail(ctx context.Context, request GetServiceDetailRequestObject) (GetServiceDetailResponseObject, error)

	// (GET /transactions)
	ListTransactions(ctx context.Context, request ListTransactionsRequestObject) (ListTransactionsResponseObject, error)

	// (POST /transactions)
	CreateTransaction(ctx context.Context, request CreateTransactionRequestObject) (CreateTransactionResponseObject, error)
	// Get transaction report by date range
	// (GET /transactions/report)
	GetTransactionReport(ctx context.Context, request GetTransactionReportRequestObject) (GetTransactionReportResponseObject, error)
	// Soft delete transaction
	// (DELETE /transactions/{id})
	SoftDeleteTransaction(ctx context.Context, request SoftDeleteTransactionRequestObject) (SoftDeleteTransactionResponseObject, error)
	// Update transaction (income)
	// (PUT /transactions/{id})
	UpdateTransaction(ctx context.Context, request UpdateTransactionRequestObject) (UpdateTransactionResponseObject, error)

	// (POST /transactions/{id}/payments)
	AddPayment(ctx context.Context, request AddPaymentRequestObject) (AddPaymentResponseObject, error)
	// Restore soft deleted transaction
	// (POST /transactions/{id}/restore)
	RestoreTransaction(ctx context.Context, request RestoreTransactionRequestObject) (RestoreTransactionResponseObject, error)
}

type StrictHandlerFunc func(ctx echo.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
}

// Login operation middleware
func (sh *strictHandler) Login(ctx echo.Context) error {
	var request LoginRequestObject

	var body LoginJSONRequestBody
	if err := ctx.Bind(&body); err != nil {
		return err
	}
	request.Body = &body

	handler := func(ctx echo.Context, request interface{}) (interface{}, error) {
		return sh.ssi.Login(ctx.Request().Context(), request.(LoginRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Login")
	}

	response, err := handler(ctx, request)

	if err != nil {
		return err
	} else if validResponse, ok := response.(LoginResponseObject); ok {
		return validResponse.VisitLoginResponse(ctx.Response())
	} else if response != nil {
		return fmt.Errorf("unexpected response type: %T", response)
	}
	return nil
}

